const webhookDeliveryStats = `-- name: WebhookDeliveryStats :one
SELECT
    COUNT(*)                                                     AS total,
    COUNT(*) FILTER (WHERE success)                              AS succeeded,
    COUNT(*) FILTER (WHERE NOT success)                          AS failed,
    COALESCE(AVG(duration_ms) FILTER (WHERE success), 0)::float8 AS avg_success_ms,
    MAX(created_at)                                              AS last_delivery_at,
    MAX(created_at) FILTER (WHERE success)                       AS last_success_at,
    MAX(created_at) FILTER (WHERE NOT success)                   AS last_failure_at
FROM webhook_deliveries
WHERE webhook_id = $1
`

type WebhookDeliveryStatsRow struct {
	Total          int64       `json:"total"`
	Succeeded      int64       `json:"succeeded"`
	Failed         int64       `json:"failed"`
	AvgSuccessMs   float64     `json:"avg_success_ms"`
	LastDeliveryAt interface{} `json:"last_delivery_at"`
	LastSuccessAt  interface{} `json:"last_success_at"`
	LastFailureAt  interface{} `json:"last_failure_at"`
}

// Aggregate delivery health for a single webhook over its stored delivery rows - retries are stored as separate rows, so total/succeeded/failed are attempt-level counts. avg_success_ms averages only successful attempts (failed/timed-out attempts would skew a "typical response time") - the three timestamps are NULL when no matching row exists
func (q *Queries) WebhookDeliveryStats(ctx context.Context, webhookID uuid.UUID) (WebhookDeliveryStatsRow, error) {
	row := q.db.QueryRowContext(ctx, webhookDeliveryStats, webhookID)
	var i WebhookDeliveryStatsRow
	err := row.Scan(
		&i.Total,
		&i.Succeeded,
		&i.Failed,
		&i.AvgSuccessMs,
		&i.LastDeliveryAt,
		&i.LastSuccessAt,
		&i.LastFailureAt,
	)
	return i, err
}
